-- Favorite adverts are private to each ASP.NET Core Identity account.
CREATE TABLE IF NOT EXISTS rentall."Favoritos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL REFERENCES rentall."AspNetUsers"("Id") ON DELETE CASCADE,
    "AnuncioId" integer NOT NULL REFERENCES rentall."Anuncios"(id) ON DELETE CASCADE,
    "CriadoEm" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_Favoritos_UserId_AnuncioId" UNIQUE ("UserId", "AnuncioId")
);
CREATE INDEX IF NOT EXISTS "IX_Favoritos_AnuncioId" ON rentall."Favoritos" ("AnuncioId");
REVOKE ALL ON rentall."Favoritos" FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA rentall FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON rentall."Favoritos" TO rentall_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA rentall TO rentall_app;
